for(const exam of reconstructionSets){
  if(!exam.opening)chapters[exam.id]={sections:topics.map(([id,title])=>[id,title,[]])};
}
for(const [topic,number,page,q,a,k,e,x] of reconItems){
  const id=topic+'-'+number;
  questions.push({id,topic,section:topicForReconstruction.get(id),number,page,q,a,k,e,x});
}
